using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
namespace CyberPW.Assistant2{internal sealed class CardPanel:Panel{public Color BorderColor=Theme.Gold;public int BorderThickness=2;public int CornerRadius=12;public CardPanel(){SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.UserPaint,true);Resize+=(s,e)=>Invalidate();}protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;int t=BorderThickness;using(var p=new GraphicsPath()){int d=CornerRadius*2;p.AddArc(t,t,d,d,180,90);p.AddArc(Width-d-t-1,t,d,d,270,90);p.AddArc(Width-d-t-1,Height-d-t-1,d,d,0,90);p.AddArc(t,Height-d-t-1,d,d,90,90);p.CloseFigure();using(var pen=new Pen(BorderColor,t))e.Graphics.DrawPath(pen,p);}}}}
